mapper.select:
select source_id,order_time from ${tableName} where is_deleted = false
and source_id in

    #{sourceId}

SELECT wdp.approve_status AS status, wdpd.qty AS qty, CASE WHEN wdp.approve_status = 'approve' THEN wdp.approve_time ELSE wdp.create_time END AS estimateSalesDate, wdp.id AS sourceId, wdp.code AS sourceCode, wdp.to_warehouse_id AS warehouseId FROM ${tableName} AS wdp INNER JOIN ${tableDetailName} AS wdpd ON wdpd.is_deleted = FALSE AND wdpd.main_id = wdp.id WHERE wdp.is_deleted = FALSE and wdp.invalid_status = 'false' AND wdp."type" = #{type}
AND wdp.shop_id = #{result.replenishment.shopId}
AND wdp.to_warehouse_id in
#{item}
AND wdpd.sku_id = #{result.replenishment.skuId}
AND wdp.source_type = 'replenishment_plan'
AND wdp.source_type = ''
AND wdp.approve_status = 'approve' AND wdp.delivery_status = 'unShipped'
AND ( (wdp.approve_status = 'approve' AND wdp.delivery_status = 'unShipped') OR wdp.approve_status IN
#{code}
)
AND wdp.approve_status IN
#{code}

SELECT sku_id, warehouse_id AS warehouseId, SUM ( qty ) AS qty FROM ${tableName} WHERE is_deleted = false AND dict_inventory_status IN
#{code}
GROUP BY warehouse_id,sku_id

SELECT sku_id, virtual_warehouse_id, SUM ( qty ) AS qty FROM ${tableName} WHERE is_deleted = false AND dict_inventory_status IN
#{code}
GROUP BY virtual_warehouse_id,sku_id

SELECT pad.sku_id, MAX ( pa.approve_status ) AS status, MAX ( pa.code ) AS sourceCode, pa.id AS sourceId, pad.dest_warehouse_id AS warehouseId, SUM ( pad.apply_qty ) AS qty, MAX ( pad.create_po_type ) AS createPoType, MAX ( COALESCE ( pa.approve_time, pa.create_time ) ) AS estimatedPutAwayDate, MAX ( pad.id ) AS detailId, 'purchaseApplication' AS sourceType FROM ${tableName} AS pa INNER JOIN ${tableDetailName} AS pad ON pad.is_deleted = FALSE AND pad.purchase_application_id = pa.id
AND pa.approve_status = 'approve' AND pad.create_po_type IN ('0', '1')
AND ( (pa.approve_status = 'approve' AND pad.create_po_type IN ('0', '1')) OR pa.approve_status IN
#{code}
)
AND pa.approve_status IN
#{code}
GROUP BY pad.sku_id,pad.dest_warehouse_id,pa.id

SELECT pod.sku_id, max(po.code) AS sourceCode, po.id AS sourceId, max(po.create_time) AS estimatedPutAwayDate, max(po.approve_status) AS status, sum(pod.purchase_qty) AS qty, po.delivery_warehouse_id AS warehouseId, 'purchaseOrder' AS sourceType FROM ${tableName} AS po INNER JOIN ${tableDetailName} AS pod ON pod.is_deleted = FALSE AND pod.purchase_order_id = po.id WHERE po.invalid_status = false and po.is_deleted = false and po.approve_status IN
#{code}
GROUP BY pod.sku_id,po.delivery_warehouse_id,po.id

select sod.id, sod.qty, sod.parent_id, sod.source_detail_id from ${tableName} so inner join ${tableDetailName} sod on so.id = sod.main_id and sod.is_deleted = false left join ${otherTableName} pod on pod.source_detail_id = sod.id and pod.is_deleted = false
so.is_deleted = false and so.invalid_status = false and pod.id is null and sod.source_detail_id in
#{item}

SELECT fmd.ID AS deliveryPlanId, fmd.code AS deliveryPlanCode, fmd.approve_status AS status, fmd.approve_time AS deliveryDate, fmdd.delivery_qty AS deliveryQty, COALESCE( (SELECT SUM (owid.receive_qty) FROM ${otherTableName} owi INNER JOIN ${otherTableDetailName} owid ON owid.is_deleted = FALSE AND owid.main_id = owi.ID AND owi.is_deleted = FALSE AND owi.source_id = fmd.ID AND owid.sku_id = #{result.replenishment.skuId}), 0 ) AS receiveQty, (fmdd.delivery_qty - COALESCE( (SELECT SUM (owid.receive_qty) FROM ${otherTableName} owi INNER JOIN ${otherTableDetailName} owid ON owid.is_deleted = FALSE AND owid.main_id = owi.ID AND owi.is_deleted = FALSE AND owi.source_id = fmd.ID AND owid.sku_id = #{result.replenishment.skuId}), 0) ) AS inTransitQty, fmd.dest_warehouse_id AS warehouseId FROM ${tableName} fmd INNER JOIN ${tableDetailName} fmdd ON fmdd.is_deleted = FALSE AND fmdd.main_id = fmd.ID WHERE fmd.is_deleted = FALSE AND fmd.demand_type = 'demandOverseasWarehouse' AND fmdd.sku_id = #{result.replenishment.skuId} AND fmd.approve_status = 'approve' AND fmd.dest_warehouse_id in
#{item}
AND (fmdd.delivery_qty - COALESCE( (SELECT SUM (owid.receive_qty) FROM ${otherTableName} owi INNER JOIN ${otherTableDetailName} owid ON owid.is_deleted = FALSE AND owid.main_id = owi.ID AND owi.is_deleted = FALSE AND owi.source_id = fmd.ID AND owid.sku_id = #{result.replenishment.skuId}), 0) ) > 0

SELECT ps.id AS sourceId, MAX ( ps.code ) AS sourceCode, MAX ( ps.status ) AS status, SUM ( CASE WHEN ps.status = 'draft' THEN 0 WHEN ps.status = 'waitConfirm' THEN ps.suggest_purchase_qty ELSE ps.plan_purchase_qty END ) AS qty, MAX ( ps.estimate_instock_date ) AS estimatedPutAwayDate, MAX ( ps.estimate_sales_date ) AS estimateSalesDate, 'replenishment_plan' AS sourceType, ps.sku_id, ps.shop_id FROM ${tableName} ps WHERE ps.invalid_status = FALSE AND ps.status IN
#{code}
GROUP BY ps.sku_id, ps.shop_id, ps.id

SELECT ps.id AS sourceId, MAX ( ps.code ) AS sourceCode, MAX ( ps.status ) AS status, SUM ( CASE WHEN ps.status = 'draft' THEN 0 WHEN ps.status = 'waitConfirm' THEN ps.suggest_purchase_qty ELSE ps.plan_purchase_qty END ) AS qty, MAX ( ps.estimate_instock_date ) AS estimatedPutAwayDate, MAX ( ps.estimate_sales_date ) AS estimateSalesDate, 'replenishment_plan' AS sourceType, ps.sku_id, ps.shop_id FROM ${tableName} ps WHERE ps.invalid_status = FALSE AND ps.status IN
#{code}
GROUP BY ps.sku_id, ps.shop_id, ps.id
